function validate([intervals]) {
  if (!Array.isArray(intervals) || intervals.length < 1 || intervals.length > 3000) return 'intervals needs 1 to 3000 entries.';
  for (const pair of intervals) {
    if (!Array.isArray(pair) || pair.length !== 2 || !pair.every(Number.isInteger)) return 'Each interval is a pair of integers [start, end].';
    if (pair[0] < 0 || pair[1] > 100000000) return 'Interval ends are between 0 and 10^8.';
    if (pair[0] >= pair[1]) return 'Each interval needs start < end.';
  }
  return null;
}

