function intersectionSizeTwo(intervals) {
  intervals.sort((a, b) => a[1] - b[1] || b[0] - a[0]);
  let count = 0;
  let secondLargest = -1;
  let largest = -1;

  for (const [start, end] of intervals) {
    if (start > largest) {
      count += 2;
      secondLargest = end - 1;
      largest = end;
    } else if (start > secondLargest) {
      count += 1;
      secondLargest = largest;
      largest = end;
    }
  }
  return count;
}

