function intersectionSizeTwo(intervals) {
  // Integers between two neighbouring cut points lie in exactly the same intervals,
  // so the first two integers of each such stretch are the only candidates needed.
  const cuts = [...new Set(intervals.flatMap(([s, e]) => [s, e + 1]))].sort((a, b) => a - b);
  const points = [];
  for (let i = 0; i + 1 < cuts.length; i++) {
    points.push(cuts[i]);
    if (cuts[i] + 1 < cuts[i + 1]) points.push(cuts[i] + 1);
  }
  // Try every subset of the candidates, counting in binary with an array of flags.
  const take = new Array(points.length).fill(false);
  let best = Infinity;
  for (;;) {
    const chosen = points.filter((_, b) => take[b]);
    if (chosen.length < best && intervals.every(([s, e]) => chosen.filter(x => x >= s && x <= e).length >= 2)) best = chosen.length;
    let b = 0;
    while (b < take.length && take[b]) take[b++] = false;
    if (b === take.length) break;
    take[b] = true;
  }
  return best;
}

