function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const reach = [10, 1000, 100000, 10000000][pick(4)];
    return [Array.from({ length: 2000 }, () => {
      const start = pick(100000000 - 1);
      const end = Math.min(100000000, start + 1 + pick(reach));
      return [start, end];
    })];
  }
  const top = 4 + pick(8);
  const n = 1 + pick(7);
  return [Array.from({ length: n }, () => {
    const start = pick(top);
    return [start, start + 1 + pick(top - start)];
  })];
}
